def calculate_total_cost(items, discount_percentage, threshold):
    total_cost = 0
    for item in items:
        total_cost += item['price'] * item['quantity']

    if total_cost > threshold:
        discount = total_cost * (discount_percentage / 100)
        total_cost -= discount

    return total_cost

def play_vinyl_record(song_titles, loop_count):
    for _ in range(loop_count):
        for song in song_titles:
            print(song)

def convert_book_titles(book_titles):
    capitalized_titles = []
    for title in book_titles:
        capitalized_title = ' '.join(word.capitalize() for word in title.split())
        capitalized_titles.append(capitalized_title)
    return '; '.join(capitalized_titles)

def are_anagrams(string1, string2):
    # Convert strings to lowercase and remove non-alphanumeric characters
    string1 = ''.join(c.lower() for c in string1 if c.isalnum())
    string2 = ''.join(c.lower() for c in string2 if c.isalnum())

    # Check if the cleaned strings have the same length
    if len(string1) != len(string2):
        return False

    # Create dictionaries to store character counts
    char_count1 = {}
    char_count2 = {}

    # Count characters in both strings
    for char in string1:
        char_count1[char] = char_count1.get(char, 0) + 1
    for char in string2:
        char_count2[char] = char_count2.get(char, 0) + 1

    # Check if the character counts are the same
    return char_count1 == char_count2

def validate_identifications(identifications):
    import re
    valid_identifications = []
    pattern = r'^[A-Z]{3}-\d{7}$'
    for identification in identifications:
        if re.match(pattern, identification):
            valid_identifications.append(identification)
    return valid_identifications

def count_victories(battles, side):
    victory_count = 0
    for battle in battles:
        if battle["winner"] == side:
            victory_count += 1
    return victory_count

def fibonacci(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

def transition_employees(employees, n):
    result = []
    for i in range(0, len(employees), n):
        result.append(employees[i:i+n])
    return result

def find_hidden_talents(performances):
    hidden_talents = []
    for performance in performances:
        if performance["rating"] >= 8:
            hidden_talents.append(performance["name"])
    return hidden_talents

def calculate_points(match_results):
    total_points = 0
    for result in match_results:
        standard_goals, opponent_goals = map(int, result.split('-'))
        if standard_goals > opponent_goals:
            total_points += 3
        elif standard_goals == opponent_goals:
            total_points += 1
    return total_points

def calculate_average_speed(distances_and_times):
    total_distance = 0
    total_time = 0

    for distance, time in distances_and_times:
        total_distance += distance
        total_time += time

    if total_time == 0:
        return 0

    average_speed = total_distance / total_time
    return average_speed
